// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(address depositor, uint256 amount, address thief) public {
        vm.assume(depositor != address(0) && thief != address(0));
        vm.assume(depositor != address(c));
        amount = bound(amount, 1, type(uint256).max / 2);
        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.deposit{value: amount}();

        uint256 balanceBefore = address(c).balance;
        vm.prank(thief);
        try c.migrateTo(address(0xdead)) {} catch {}
        uint256 balanceAfter = address(c).balance;

        assertTrue(balanceAfter > 0);
    }
}
